import {copperLayers,padOnLayer,arcPath,hitNets,netDetails} from './pcb-geometry.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={'F.Cu':'#ed8c80','B.Cu':'#78a9f6'};
const points=p=>p.map(x=>x.join(',')).join(' ');
function padShape(p){const [w,h]=p.size,transform=`translate(${p.x} ${p.y}) rotate(${-p.angle})`;if(p.shape==='circle')return `<circle transform="${transform}" r="${w/2}"/>`;const radius=p.shape==='oval'?Math.min(w,h)/2:p.shape==='roundrect'?Math.min(w,h)*p.roundrect_ratio:0;return `<rect transform="${transform}" x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="${radius}"/>`;}
function drillShape(p){if(!p.drill?.length)return '';const oval=p.drill[0]==='oval',w=+(oval?p.drill[1]:p.drill[0]),h=oval?+p.drill[2]:w;return padShape({...p,shape:oval?'oval':'circle',size:[w,h]});}
function outlineShape(p){if(p.kind==='gr_rect')return `<rect x="${p.start[0]}" y="${p.start[1]}" width="${p.end[0]-p.start[0]}" height="${p.end[1]-p.start[1]}"/>`;if(p.kind==='gr_arc')return `<path d="${arcPath(p)}"/>`;return `<path d="M ${p.start.join(' ')} L ${p.end.join(' ')}"/>`;}
export function pcbSvg(data,side,silks){const b=data.bounds,x=b.minX-1,y=b.minY-1,w=b.maxX-b.minX+2,h=b.maxY-b.minY+2,layers=copperLayers(side);const item=(id,type,body)=>`<g class="pcb-copper pcb-${type}" data-net="${id}">${body}</g>`;
 const layer=(l)=>`<g data-copper-layer="${l}" fill="${colors[l]}" stroke="${colors[l]}" stroke-linecap="round" stroke-linejoin="round">${data.zones.filter(z=>z.layer===l).map(z=>item(z.net_id,'zone',`<polygon points="${points(z.points)}" stroke="none" fill-rule="evenodd"/>`)).join('')}</g>`;
 const wires=(l)=>`<g data-copper-layer="${l}" fill="${colors[l]}" stroke="${colors[l]}" stroke-linecap="round" stroke-linejoin="round">${data.tracks.filter(t=>t.layer===l).map(t=>item(t.net_id,'track',`<path d="${t.kind==='arc'?arcPath(t):`M ${t.start.join(' ')} L ${t.end.join(' ')}`}" fill="none" stroke-width="${t.width}"/>`)).join('')}${data.components.flatMap(c=>c.pads.filter(p=>padOnLayer(p,l)).map(p=>item(p.net_id,'pad',`<g stroke="none"><title>${esc(c.ref+'-'+p.number+' · '+p.net)}</title>${padShape(p)}</g>`))).join('')}</g>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${x} ${y} ${w} ${h}" class="cad-image pcb-svg" role="img" aria-label="PCB 铜层和网络" data-side="${side}"><style>.pcb-zone{opacity:.13}.pcb-track,.pcb-pad,.pcb-via{opacity:.85}.pcb-svg.has-selection .pcb-copper{opacity:.13}.pcb-svg.has-selection .pcb-zone{opacity:.035}.pcb-svg.has-selection .pcb-selected{opacity:1;filter:drop-shadow(0 0 .05px #fff5a6)}.pcb-svg.has-selection .pcb-selected:not(.pcb-zone){fill:#ffe8a3;stroke:#ffe8a3}.pcb-svg.has-selection .pcb-selected.pcb-via{stroke:none}.pcb-svg.has-selection .pcb-selected.pcb-zone{opacity:.25;fill:#ffe8a3;stroke:none}</style><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#162b30"/>${layers.map(layer).join('')}${layers.map(wires).join('')}<g fill="#c8d6c9" stroke="none">${data.vias.map(v=>item(v.net_id,'via',`<circle cx="${v.at[0]}" cy="${v.at[1]}" r="${v.size/2}"/>`)).join('')}</g><g fill="#162b30" stroke="none">${data.vias.map(v=>`<circle cx="${v.at[0]}" cy="${v.at[1]}" r="${v.drill/2}"/>`).join('')}${data.components.flatMap(c=>c.pads.filter(p=>layers.some(l=>padOnLayer(p,l))).map(drillShape)).join('')}</g><g fill="none" stroke="#c7d7c5" stroke-width=".07">${data.outline.map(outlineShape).join('')}</g><g class="pcb-silk" opacity=".85">${(side==='back'?['B.Cu']:['F.Cu']).map(l=>`<image x="${x}" y="${y}" width="${w}" height="${h}" href="${esc(silks[l==='F.Cu'?'front':'back'])}"/>`).join('')}</g></svg>`;
}
export async function loadPcb(board){const root=`hardware/${board}/`;const resources=await Promise.all(['geometry.json','pcb-silk-front.svg','pcb-silk-back.svg'].map(async file=>{const res=await fetch(root+file);if(!res.ok)throw Error(`${file}: HTTP ${res.status}`);return file.endsWith('.json')?res.json():res.text();}));return {data:resources[0],silks:{front:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(resources[1]),back:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(resources[2])}};}
export function mountPcb(host,board,side,resources,panzoom){const {data,silks}=resources;host.innerHTML=pcbSvg(data,side,silks);const svg=host.querySelector('svg'),bar=document.querySelector('#pcb-net-bar'),details=bar.querySelector('.pcb-net-details'),select=bar.querySelector('#pcb-net-select'),choices=bar.querySelector('.pcb-net-choices'),clear=bar.querySelector('[data-net-clear]'),silk=bar.querySelector('#pcb-show-silk');let selected=null,fileUrl=null;const download=document.querySelector('#cad-source-link');
 const updateDownload=()=>{const clone=svg.cloneNode(true);clone.removeAttribute('style');clone.setAttribute('width','1200');clone.setAttribute('height',String(Math.round(1200*svg.viewBox.baseVal.height/svg.viewBox.baseVal.width)));if(side==='back'){const content=document.createElementNS('http://www.w3.org/2000/svg','g');content.setAttribute('transform',`translate(${data.bounds.minX+data.bounds.maxX} 0) scale(-1 1)`);while(clone.firstChild)content.appendChild(clone.firstChild);clone.appendChild(content);}if(fileUrl)URL.revokeObjectURL(fileUrl);fileUrl=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml'}));download.href=fileUrl;download.download=`${board}-pcb-${side}${selected?'-net-'+selected:''}.svg`;download.removeAttribute('aria-disabled');download.textContent='下载当前 PCB SVG ↓';};
 const netIds=Object.keys(data.nets).map(Number).filter(id=>id>0).sort((a,b)=>data.nets[a].localeCompare(data.nets[b]));select.innerHTML='<option value="">点击走线或选择网络…</option>'+netIds.map(id=>`<option value="${id}">${esc(data.nets[id])}</option>`).join('');select.disabled=false;
 const choose=id=>{selected=id;svg.classList.toggle('has-selection',id!==null);svg.querySelectorAll('[data-net]').forEach(el=>el.classList.toggle('pcb-selected',id!==null&&+el.dataset.net===id));select.value=id===null?'':String(id);clear.disabled=id===null;host.dataset.net=id===null?'':String(id);updateDownload();if(id===null){details.textContent='点击走线、焊盘或过孔，查看整个网络。';return;}const d=netDetails(data,id);details.innerHTML=`<b>${esc(d.name)}</b><span>${esc(d.layers.join(' + '))} · ${d.pins.length} 个焊盘</span><span class="pcb-connected-pins" title="${esc(d.pins.join('，'))}">${esc(d.pins.slice(0,16).join('，'))}${d.pins.length>16?'…':''}</span>`;};
 const resetSelection=()=>{choose(null);choices.replaceChildren();};select.onchange=()=>{choices.replaceChildren();choose(select.value?+select.value:null);};clear.onclick=resetSelection;
 silk.onchange=()=>{svg.querySelector('.pcb-silk').style.display=silk.checked?'':'none';updateDownload();};
 const onSelect=(e)=>{const matrix=svg.getScreenCTM();if(!matrix)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse()),pxPerMM=Math.hypot(matrix.a,matrix.b),hits=hitNets(data,p.x,p.y,side,5/pxPerMM);if(!hits.length){resetSelection();return;}choose(hits[0].id);choices.innerHTML=hits.length>1?'<span>此处附近有多个网络：</span>'+hits.map(hit=>`<button class="small" data-net-choice="${hit.id}">${esc(data.nets[hit.id])}</button>`).join(''):'';choices.querySelectorAll('[data-net-choice]').forEach(btn=>btn.onclick=()=>choose(+btn.dataset.netChoice));};
 const dispose=panzoom(host,svg,side==='back',{onSelect,onClear:resetSelection});choose(null);
 return ()=>{dispose();if(fileUrl)URL.revokeObjectURL(fileUrl);select.onchange=clear.onclick=silk.onchange=null;};
}
